package tokenizer

import scala.collection.mutable
import scala.collection.mutable.ListBuffer
import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import java.util.Locale
import io.circe.{Json, Printer}

// ==========================================================================
// Protocol-style traits
// ==========================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ==========================================================================
// Enums and constants
// ==========================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ==========================================================================
// Core token classes
// ==========================================================================

final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries)
}

class MutableTokenBatch(initial: Seq[Token] = Seq.empty) {
  private val buffer = ListBuffer(initial: _*)
  private var processed = false

  def tokens: List[Token] = buffer.toList

  def add(token: Token): Unit = {
    if (processed) throw new RuntimeException("Batch already processed")
    buffer += token
  }

  def markProcessed(): Unit = {
    processed = true
  }
}

// ==========================================================================
// Generic container classes
// ==========================================================================

class TokenContainer[+T](items: Seq[T]) {
  private val stored: Vector[T] = items.toVector

  def getAll: Vector[T] = stored

  def mapTokens(func: T => String): List[String] = stored.map(func).toList

  def size: Int = stored.size
}

class TokenSink[-T] {
  private val received = ListBuffer.empty[Any]

  def receive(item: T): Unit = received += item

  def drain(): List[Any] = {
    val result = received.toList
    received.clear()
    result
  }
}

class BivariantHandler[T](default: T) {
  private var value: T = default

  def get: T = value

  def set(v: T): Unit = {
    value = v
  }

  def transform(func: T => T): T = {
    value = func(value)
    value
  }
}

// ==========================================================================
// Tokenizer implementations
// ==========================================================================

abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case bytes: Array[Byte] => new String(bytes, encoding)
      case s: String          => s
      case other              => other.toString
    }
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.STRING)
  }
}

class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  private def formatFloating(d: Double): String =
    String.format(Locale.US, s"%.${precision}f", Double.box(d))

  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case bd: BigDecimal =>
        bd.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString
      case d: Double => formatFloating(d)
      case f: Float  => formatFloating(f.toDouble)
      case bi: BigInt => bi.toString
      case i: Int    => i.toString
      case l: Long   => l.toString
      case s: Short  => s.toString
      case b: Byte   => b.toString
      case other     => other.toString
    }

    val originalType = Option(value).map(_.getClass.getSimpleName).getOrElse("null")
    Token(strValue, TokenType.NUMERIC, Map("original_type" -> originalType))
  }
}

class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  private val isoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  override def tokenize(value: Any): Token = {
    val formatter = formatStr.map(DateTimeFormatter.ofPattern)
    val strValue = value match {
      case dt: LocalDateTime => formatter.getOrElse(isoFormat).format(dt)
      case d: LocalDate      => formatter.getOrElse(dateFormat).format(d)
      case other =>
        formatter
          .map(_.format(other.asInstanceOf[java.time.temporal.TemporalAccessor]))
          .getOrElse(other.toString)
    }
    Token(strValue, TokenType.TEMPORAL)
  }
}

